SELECT COUNT(DISTINCT case_id) FROM (
    SELECT case_id FROM dtl_case_view WHERE viewed_at >= #{since}
    UNION
    SELECT case_id FROM dtl_case_like WHERE liked_at >= #{since}
    UNION
    SELECT case_id FROM dtl_case_comment
     WHERE deleted = FALSE AND commented_at >= #{since}
) t

SELECT COUNT(*) FROM biz_case
 WHERE deleted = FALSE
   AND case_state = #{publishedState}
   AND published_at IS NOT NULL
   AND published_at >= #{from}
   AND published_at < #{to}
